const out = [];
const support = ($env.SUPPORT_FROM_EMAIL || '').toLowerCase();
for (const { json: m } of $input.all()) {
  const from = m.from?.value?.[0] || {};
  let address = from.address || '';
  if (!address && typeof m.from === 'string') address = (m.from.match(/<([^>]+)>/) || [null, m.from])[1];
  address = (address || '').trim().toLowerCase();
  if (!address || address === support) continue;                // évite les boucles
  const headers = m.headers || {};
  if (/auto-(replied|generated)/i.test(JSON.stringify(headers['auto-submitted'] || ''))) continue;
  let text = m.text || m.textPlain || String(m.html || m.textHtml || '').replace(/<[^>]+>/g, ' ');
  text = text.replace(/\r/g, '')
             .split(/\n-- \n|\n>|\nLe .{5,80} a écrit ?:|\nOn .{5,80} wrote:/)[0].trim();  // retire l'historique cité
  if (!text) continue;
  out.push({ json: {
    external_id: m.messageId || m.metadata?.['message-id'] || `${address}|${m.date}|${m.subject}`,
    customer_name: from.name || null, customer_email: address,
    subject: (m.subject || '(sans objet)').slice(0, 200), message: text.slice(0, 10000),
  } });
}
return out;
